import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { Fragment, createElement } from 'react';
import type { ComponentType, ReactElement } from 'react';
import { forSlot } from './registry';

// ── Slots: regions of the UI that features fill ───────────────────────────────────────────────
// A SLOT is a region of the UI that features fill. Whatever renders a region does not list what
// goes in it; a contribution to a region (a panel, a table column, a row action, a toolbar
// control, a nav link) is a separate file, registered by discovery (slots/discover.ts).
//
//   1. declare a region  ->  slots/defs/projectDetail.ts
//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
//   3. fill it           ->  features/projects/notes.slot.tsx
//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
//
// This file, slots/registry.ts and slots/discover.ts implement that mechanism; a region is
// declared by a file under slots/defs/.

export type Contribution<Ctx> = {
  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
  order?: number;
  Component: ComponentType<Ctx>;
};

export type SlotDef<Ctx extends object> = {
  id: string;
  /** Renders the region. Its props ARE the context handed to every contribution. */
  Slot: (ctx: Ctx) => ReactElement;
  /** A feature wraps its contribution in this, to be typed against the region's context. */
  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
};

export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
  return {
    id,
    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
    // row actions are slots too), where a stray <div> would be invalid markup.
    Slot: (ctx: Ctx) =>
      createElement(
        Fragment,
        null,
        forSlot(id).map((c) =>
          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
        ),
      ),
    fill: (contribution) => ({ slot: id, ...contribution }),
  };
}
import { HomeMain } from '../../slots/defs/homeMain';
import { DueTotal } from './DueTotal';
import { Rates } from './Rates';

export const contributions = [
  HomeMain.fill({ order: 5, Component: Rates }),
  HomeMain.fill({ order: 40, Component: DueTotal }),
];
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { GRADES } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { NA, PERCENT, rateFor, ratesKey, useRates } from './rates';
import type { Rate, RateInput } from './rates';
import { useOneAtATime } from '../../query/useOneAtATime';

const EMPTY: RateInput = { grade: 'A', rate: '', from: '' };

/** yyyy-MM-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;

// Each grade's rate in force on the sheet's today (n/a when none is), every rate the sheet has with
// its from-date, and the form that sets one.
export function Rates() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const rates = useRates().data ?? [];
  const today = useSheetToday();
  const [form, setForm] = useState<RateInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (input: RateInput) =>
      putJson<Rate>(`/api/sheets/${encodeURIComponent(sheet)}/rates?user=${encodeURIComponent(user)}`, input),
    onSuccess: async () => {
      setForm((f) => ({ ...f, rate: '', from: '' }));
      setError('');
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheet) });
    },
    onError: () => setError('That rate could not be set.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!PERCENT.test(form.rate.trim())) {
      setError('Type a percent of 0.00 or more, with at most two decimals.');
      return;
    }
    const from = form.from.trim();
    if (from !== '' && !DATE.test(from)) {
      setError('Type a from-date as yyyy-mm-dd, or leave it blank for from the start.');
      return;
    }
    once(() => save.mutateAsync({ grade: form.grade, rate: form.rate.trim(), from }));
  };

  const change = (patch: Partial<RateInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <section data-testid="rates">
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateFor(rates, g, today) ?? NA}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td data-testid="rate-pct">{r.rate}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form onSubmit={submit} data-testid="rate-form">
        <select data-testid="rate-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
        <input
          data-testid="rate-form-pct"
          placeholder="Rate %"
          value={form.rate}
          onChange={(e) => change({ rate: e.target.value })}
        />
        <input
          data-testid="rate-form-from"
          placeholder="From yyyy-mm-dd (blank: from the start)"
          value={form.from}
          onChange={(e) => change({ from: e.target.value })}
        />
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {error && <span data-testid="rate-form-error">{error}</span>}
      </form>
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { sheetKey, useCurrentSheet } from '../session/session';

/**
 * A grade's rate as the store holds it: a percent with two decimals, in force from its from-date
 * (yyyy-MM-dd; null: from the beginning of time) until the grade's next rate takes over.
 */
export type Rate = { grade: string; rate: string; from: string | null };

/** The fields the rate form submits; a blank from-date is from the beginning of time. */
export type RateInput = { grade: string; rate: string; from: string };

/** What a due shows when its grade has no rate. */
export const NA = 'n/a';

/** 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** The query key for the sheet's rates; under sheetKey, so re-loading the sheet re-reads them. */
export const ratesKey = (sheet: string) => [...sheetKey(sheet), 'rates'] as const;

/** The sheet's rates, by grade and then from-date (from the start first). */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: !!sheet,
  });
}

/**
 * The grade's rate (two decimals) in force on the date: the one with the latest from-date on or
 * before it, a rate with no from-date applying from the start; undefined when none applies.
 */
export function rateFor(rates: Rate[], grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (!found || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.rate;
}

/** A two-decimal value as whole hundredths, exactly. */
const hundredths = (value: string) => Math.round(Number(value) * 100);

/**
 * An amount times a percent rate, divided by 100, rounded half to even to two decimals; n/a with no
 * rate. Worked in whole hundredths so it is exact: cents × basis points / 10000.
 */
export function due(amount: string, rate: string | undefined): string {
  if (rate === undefined) return NA;
  const product = hundredths(amount) * hundredths(rate);
  const whole = Math.floor(Math.abs(product) / 10000);
  const rest = Math.abs(product) - whole * 10000;
  const up = rest > 5000 || (rest === 5000 && whole % 2 === 1);
  const cents = Math.sign(product) * (whole + (up ? 1 : 0));
  return (cents / 100).toFixed(2);
}

/**
 * A claim's figure: the due fixed when it was settled, else the figure its statement bound it to,
 * else its amount at the rate in force on its date for the grade.
 */
export function claimDue(claim: Claim, rates: Rate[], grade: string): string {
  if (claim.due !== null) return claim.due;
  if (claim.stated) return claim.statedDue ?? NA;
  return due(claim.amount, rateFor(rates, grade, claim.date));
}

/** Whether a claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
const keepsFigure = (c: Claim) => c.due !== null || (c.stated && c.statedDue !== null);

/**
 * A person's due-total: the figures of their claims that count, added up (0.00 with none). With no
 * rate in force on the sheet's today for their grade it is n/a, unless a settled or stated claim
 * keeps a figure: then it is the figures there are, added up. While they are held, their open claims do not count.
 */
export function personDue(claims: Claim[], rates: Rate[], grade: string, today: string, held: boolean): string {
  const counted = claims.filter((c) => counts(c, held));
  const figures = counted.map((c) => claimDue(c, rates, grade));
  if (rateFor(rates, grade, today) === undefined && !counted.some(keepsFigure)) {
    return NA;
  }
  return total(figures);
}

/** Dues added up, skipping n/a; with two decimals, added in cents so it is exact. */
export function total(dues: string[]): string {
  const cents = dues.filter((d) => d !== NA).reduce((sum, d) => sum + hundredths(d), 0);
  return (cents / 100).toFixed(2);
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
