import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import type { Claim } from './claims';
import { claimsKey } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';

type Action = 'open' | 'settle' | 'void';

const ACTIONS: Array<{ action: Action; label: string }> = [
  { action: 'open', label: 'Open' },
  { action: 'settle', label: 'Settle' },
  { action: 'void', label: 'Void' },
];

// A claim's status and the buttons that change it. Every button is shown; the server refuses a
// change the status does not allow, and the refusal shows as the claim's error.
export function ClaimStatus({ claim }: { claim: Claim }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const change = useMutation({
    mutationFn: (action: Action) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/${action}?user=${encodeURIComponent(user)}`,
        {},
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: (_e, action) => setError(`This ${claim.status} claim cannot be changed by ${action}${action === 'settle' ? ' (the user who opened it cannot settle it)' : ''}.`),
  });

  return (
    <>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, label }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
          onClick={() => {
            setError('');
            once(() => change.mutateAsync(action));
          }}
        >
          {label}
        </button>
      ))}
      {error && <span data-testid="claim-error">{error}</span>}
    </>
  );
}
import { HomeMain } from '../../slots/defs/homeMain';
import { Periods } from './Periods';

export const contribution = HomeMain.fill({ order: 7, Component: Periods });
import { defineSlot } from '../Slot';

/** The home page's body: each feature on the one screen contributes its own panel. */
export const HomeMain = defineSlot('home.main');
import { asString, useSearchParam } from '../../url/useSearchParam';

// The session lives in the URL: `user` is the signed-in name, `sheet` the active sheet id. Each
// browser keeps its own, so two users on one sheet act independently.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

/** The query key under which everything kept per sheet lives; re-loading a sheet invalidates it. */
export const sheetKey = (sheet: string) => ['sheet', sheet] as const;

/** A sheet as the store holds it: its id and its own "today" (yyyy-MM-dd). */
export type SheetInfo = { id: string; today: string };

/** The query key for the sheet itself; under sheetKey, so re-loading the sheet re-reads it. */
export const sheetInfoKey = (sheet: string) => [...sheetKey(sheet), 'info'] as const;

